import { searchComponentsByQuery, getComponentData } from '../utils/dataLoader.js';

/**
 * Recommend suitable animation components based on user requirements
 */
export async function recommendAnimations(args) {
  const { 
    requirement, 
    codeContext = '', 
    priority = 'user-experience', 
    techStack = 'js-css' 
  } = args;

  try {
    // Parse user requirement
    const parsedRequirement = parseUserRequirement(requirement);
    
    // Get recommendations based on requirement
    const recommendations = await generateRecommendations(
      parsedRequirement, 
      codeContext, 
      priority, 
      techStack
    );

    // Format response
    const responseText = formatRecommendationsResponse(
      requirement,
      parsedRequirement,
      recommendations,
      priority,
      techStack
    );

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error generating recommendations: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Parse user requirement into structured data
 */
function parseUserRequirement(requirement) {
  const req = requirement.toLowerCase();
  
  const parsed = {
    intent: 'general',
    elements: [],
    effects: [],
    context: '',
    urgency: 'normal',
    keywords: req.split(/\s+/)
  };

  // Detect intent
  if (req.includes('loading') || req.includes('加载')) {
    parsed.intent = 'loading';
  } else if (req.includes('hover') || req.includes('悬停')) {
    parsed.intent = 'hover';
  } else if (req.includes('click') || req.includes('点击')) {
    parsed.intent = 'click';
  } else if (req.includes('scroll') || req.includes('滚动')) {
    parsed.intent = 'scroll';
  } else if (req.includes('transition') || req.includes('过渡')) {
    parsed.intent = 'transition';
  } else if (req.includes('background') || req.includes('背景')) {
    parsed.intent = 'background';
  } else if (req.includes('text') || req.includes('文字')) {
    parsed.intent = 'text';
  } else if (req.includes('card') || req.includes('卡片')) {
    parsed.intent = 'card';
  } else if (req.includes('button') || req.includes('按钮')) {
    parsed.intent = 'button';
  } else if (req.includes('menu') || req.includes('菜单')) {
    parsed.intent = 'menu';
  } else if (req.includes('gallery') || req.includes('画廊') || req.includes('图片')) {
    parsed.intent = 'gallery';
  }

  // Detect elements
  const elementPatterns = {
    card: /card|卡片/,
    button: /button|按钮/,
    list: /list|列表/,
    menu: /menu|菜单/,
    modal: /modal|弹窗|对话框/,
    form: /form|表单/,
    image: /image|图片|图像/,
    text: /text|文字|标题/,
    background: /background|背景/,
    navigation: /nav|导航/
  };

  Object.entries(elementPatterns).forEach(([element, pattern]) => {
    if (pattern.test(req)) {
      parsed.elements.push(element);
    }
  });

  // Detect desired effects
  const effectPatterns = {
    smooth: /smooth|平滑|流畅/,
    bounce: /bounce|弹跳|弹性/,
    fade: /fade|淡入|淡出/,
    slide: /slide|滑动|滑入/,
    rotate: /rotate|旋转/,
    scale: /scale|缩放|放大/,
    glow: /glow|发光|光效/,
    particle: /particle|粒子/,
    wave: /wave|波浪|涟漪/,
    elastic: /elastic|弹性/,
    magnetic: /magnetic|磁性|吸附/,
    parallax: /parallax|视差/,
    morphing: /morph|变形/,
    liquid: /liquid|液体|流体/,
    glass: /glass|玻璃|毛玻璃/
  };

  Object.entries(effectPatterns).forEach(([effect, pattern]) => {
    if (pattern.test(req)) {
      parsed.effects.push(effect);
    }
  });

  // Detect urgency/quality indicators
  if (req.includes('urgent') || req.includes('quick') || req.includes('急') || req.includes('快')) {
    parsed.urgency = 'high';
  } else if (req.includes('beautiful') || req.includes('stunning') || req.includes('amazing') || 
             req.includes('好看') || req.includes('漂亮') || req.includes('炫酷')) {
    parsed.urgency = 'quality';
  }

  return parsed;
}

/**
 * Generate recommendations based on parsed requirement
 */
async function generateRecommendations(parsedReq, codeContext, priority, techStack) {
  const recommendations = [];
  
  // Get component data
  const componentData = getComponentData();
  if (!componentData) {
    throw new Error('Component data not available');
  }

  // Intent-based recommendations
  const intentRecommendations = getIntentBasedRecommendations(parsedReq.intent);
  
  // Element-based recommendations
  const elementRecommendations = getElementBasedRecommendations(parsedReq.elements);
  
  // Effect-based recommendations
  const effectRecommendations = getEffectBasedRecommendations(parsedReq.effects);

  // Combine and score recommendations
  const allRecommendations = [
    ...intentRecommendations,
    ...elementRecommendations,
    ...effectRecommendations
  ];

  // Remove duplicates and score
  const uniqueRecommendations = {};
  allRecommendations.forEach(rec => {
    if (!uniqueRecommendations[rec.component]) {
      uniqueRecommendations[rec.component] = {
        component: rec.component,
        reasons: [rec.reason],
        score: rec.score,
        category: rec.category
      };
    } else {
      uniqueRecommendations[rec.component].reasons.push(rec.reason);
      uniqueRecommendations[rec.component].score += rec.score;
    }
  });

  // Convert to array and sort by score
  const sortedRecommendations = Object.values(uniqueRecommendations)
    .sort((a, b) => b.score - a.score)
    .slice(0, 6); // Top 6 recommendations

  // Enrich with component details
  for (const rec of sortedRecommendations) {
    const componentInfo = findComponentInfo(rec.component, componentData);
    if (componentInfo) {
      rec.description = componentInfo.description;
      rec.category = componentInfo.category;
      rec.techStack = techStack;
      rec.installCommand = `jsrepo add react-bits/${rec.component}`;
      rec.usageComplexity = getUsageComplexity(rec.component);
      rec.performanceImpact = getPerformanceImpact(rec.component);
    }
  }

  return sortedRecommendations;
}

