/**
 * Find component info in component data
 */
function findComponentInfo(componentName, componentData) {
  for (const category of Object.values(componentData)) {
    if (category[componentName]) {
      return category[componentName];
    }
  }
  return null;
}

/**
 * Get usage complexity for component
 */
function getUsageComplexity(componentName) {
  const complexityMap = {
    'orb': 'low',
    'particles': 'medium',
    'spotlight-card': 'low',
    'stack': 'medium',
    'dock': 'medium',
    'liquid-chrome': 'high',
    'fluid-glass': 'high',
    'model-viewer': 'high',
    'infinite-scroll': 'low',
    'bounce-cards': 'low',
    'elastic-slider': 'low'
  };
  
  return complexityMap[componentName] || 'medium';
}

/**
 * Get performance impact for component
 */
function getPerformanceImpact(componentName) {
  const impactMap = {
    'orb': 'medium',
    'particles': 'high',
    'liquid-chrome': 'high',
    'fluid-glass': 'high',
    'model-viewer': 'high',
    'spotlight-card': 'low',
    'bounce-cards': 'low',
    'elastic-slider': 'low',
    'infinite-scroll': 'low'
  };
  
  return impactMap[componentName] || 'medium';
}

/**
 * Format recommendations response
 */
function formatRecommendationsResponse(originalReq, parsedReq, recommendations, priority, techStack) {
  let output = `# Animation Recommendations\n\n`;
  
  output += `**Your Request:** "${originalReq}"\n`;
  output += `**Detected Intent:** ${parsedReq.intent}\n`;
  output += `**Priority:** ${priority}\n`;
  output += `**Tech Stack:** ${techStack}\n\n`;

  if (parsedReq.elements.length > 0) {
    output += `**Target Elements:** ${parsedReq.elements.join(', ')}\n`;
  }
  
  if (parsedReq.effects.length > 0) {
    output += `**Desired Effects:** ${parsedReq.effects.join(', ')}\n`;
  }
  
  output += '\n';

  // Recommendations
  output += `## Recommended Components\n\n`;
  
  recommendations.forEach((rec, index) => {
    output += `### ${index + 1}. ${rec.component}\n`;
    output += `**Category:** ${rec.category}\n`;
    output += `**Description:** ${rec.description}\n`;
    output += `**Why recommended:** ${rec.reasons.join(', ')}\n`;
    output += `**Usage complexity:** ${rec.usageComplexity}\n`;
    output += `**Performance impact:** ${rec.performanceImpact}\n`;
    output += `**Install:** \`${rec.installCommand}\`\n\n`;
  });

  // Next steps
  output += `## Next Steps\n\n`;
  output += `1. **Get component code:** Use \`get-react-bits-component --componentName [component-name] --version ${techStack}\`\n`;
  output += `2. **See demo:** Use \`get-react-bits-demo --componentName [component-name]\`\n`;
  output += `3. **Integration help:** Use \`generate-integration-code\` with your existing code\n`;
  output += `4. **Complete solution:** Use \`optimize-frontend-with-animations\` for full implementation\n\n`;

  // Tips
  output += `## Implementation Tips\n\n`;
  output += `- Start with the highest-scored recommendation\n`;
  output += `- Consider performance impact for your target devices\n`;
  output += `- Test animations on different screen sizes\n`;
  output += `- Use React.memo() for components that re-render frequently\n`;

  return output;
}
